def maximum_valid_pair_distance(nums1, nums2):
 left=0;answer=0
 for right,value in enumerate(nums2):
  while left<len(nums1) and nums1[left]>value:left+=1
  if left<len(nums1) and left<=right:answer=max(answer,right-left)
 return answer

